param([Parameter(Mandatory=$true)][string]$OutputDirectory,[Parameter(Mandatory=$true)][string]$NativeBuildDirectory)
$ErrorActionPreference='Stop';if($PSVersionTable.PSVersion.Major -lt 7){throw 'Use pwsh.exe'}
$mwCTRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$mwCTOut=[IO.Path]::GetFullPath($OutputDirectory);$mwCTAllowed=Join-Path $mwCTRoot 'reports/m4-crt-control-carry';$mwCTName=Split-Path $mwCTOut -Leaf
if(-not $mwCTOut.StartsWith($mwCTAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or $mwCTName -notmatch '^[a-z][a-z0-9-]{0,63}$' -or $mwCTName -match '^(con|prn|aux|nul|com[0-9]|lpt[0-9])$'){throw 'Fresh private context evidence required'}
$mwCTBuild=Join-Path $mwCTRoot "build/m4-crt-control-carry-$mwCTName";if((Test-Path -LiteralPath $mwCTOut) -or (Test-Path -LiteralPath $mwCTBuild)){throw 'Fresh context report/build required'}
function Get-MWCTHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$mwCTNativeDirectory=(Resolve-Path -LiteralPath $NativeBuildDirectory).Path;if(-not $mwCTNativeDirectory.StartsWith($mwCTAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Private native build dependency required'}
$mwCTNative=Join-Path $mwCTNativeDirectory 'build.json';$mwCTMap=Get-Content -Raw -LiteralPath $mwCTNative|ConvertFrom-Json;if(-not $mwCTMap.passed){throw 'Exact successful native build required'}
foreach($mwCTGroup in @('sources','tools','artifacts')){foreach($mwCTProperty in $mwCTMap.$mwCTGroup.PSObject.Properties){if((Get-MWCTHash $mwCTProperty.Name) -ne $mwCTProperty.Value){throw 'Frozen native context dependency identity changed'}}}
$mwCTSources=[ordered]@{};foreach($mwCTProperty in $mwCTMap.sources.PSObject.Properties){$mwCTSources[$mwCTProperty.Name]=$mwCTProperty.Value};foreach($mwCTFile in @(Get-Item -LiteralPath $PSCommandPath;Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'context-tests') -File;Get-ChildItem -LiteralPath (Join-Path $mwCTRoot 'tests/m4-crt-control-carry') -File)){$mwCTSources[$mwCTFile.FullName]=Get-MWCTHash $mwCTFile.FullName}
New-Item -ItemType Directory $mwCTOut|Out-Null;$mwCTCopies=[Collections.Generic.List[object]]::new();foreach($mwCTPath in $mwCTSources.Keys){$mwCTCopy=Join-Path (Join-Path $mwCTOut 'sources') ([IO.Path]::GetRelativePath($mwCTRoot,$mwCTPath));New-Item -ItemType Directory -Force -Path (Split-Path $mwCTCopy)|Out-Null;Copy-Item -LiteralPath $mwCTPath -Destination $mwCTCopy;$mwCTCopies.Add([ordered]@{original_path=$mwCTPath;preserved_path=$mwCTCopy;sha256=$mwCTSources[$mwCTPath]});if((Get-MWCTHash $mwCTCopy) -ne $mwCTSources[$mwCTPath]){throw 'Exact context literal source preservation'}}
$mwCTDerived=Split-Path $mwCTMap.generation;$mwCTOriginal=$mwCTMap.original_raw_path
foreach($mwCTLevel in @('O0','O2')){
 $mwCTLines=@('set(MW34_CONTEXT_OBJECTS')+@($mwCTMap.objects.$mwCTLevel.PSObject.Properties|ForEach-Object {'  "'+$_.Name.Replace('\','/')+'"'})+@(')')
 $mwCTLines|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mwCTOut "objects-$mwCTLevel.cmake")
}
$mwCTCommands=[Collections.Generic.List[object]]::new()
function Invoke-MWCT([string]$Program,[string[]]$Arguments,[string]$Log){[IO.File]::WriteAllText($Log,'');$mwCTSaved=$ErrorActionPreference;$ErrorActionPreference='Continue';try{& $Program @Arguments 2>&1|Tee-Object -FilePath $Log;$mwCTExit=$LASTEXITCODE}finally{$ErrorActionPreference=$mwCTSaved};$mwCTCommands.Add([ordered]@{program=$Program;arguments=$Arguments;exit_code=$mwCTExit;log_path=$Log;log_sha256=(Get-MWCTHash $Log)});if($mwCTExit -ne 0){throw "Context tool failed $Program exit=$mwCTExit"}}
$mwCTVS='C:/Program Files/Microsoft Visual Studio/18/Community';$mwCTLLVM=Join-Path $mwCTRoot 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc';$mwCTPassed=$false;$mwCTFailure=$null
try{
 Import-Module (Join-Path $mwCTVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $mwCTVS -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null
 $mwCTCMake=Join-Path $mwCTVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe';$mwCTCTest=Join-Path $mwCTVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/ctest.exe';$mwCTNinja=Join-Path $mwCTVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/Ninja/ninja.exe';$env:PATH="$mwCTLLVM/bin;$(Split-Path $mwCTNinja);$env:PATH";$mwCTTemp=Join-Path $mwCTOut 'compiler-temp';New-Item -ItemType Directory $mwCTTemp|Out-Null;$env:TEMP=$mwCTTemp;$env:TMP=$mwCTTemp;$env:TMPDIR=$mwCTTemp
 Invoke-MWCT $mwCTCMake @('-G','Ninja','-S',(Join-Path $PSScriptRoot 'context-tests'),'-B',$mwCTBuild,'-DCMAKE_BUILD_TYPE=Release',"-DCMAKE_CXX_COMPILER=$mwCTLLVM/bin/clang-cl.exe",'-DCMAKE_CXX_FLAGS_RELEASE=/O2 /DNDEBUG',"-DMW34_DERIVED=$mwCTDerived","-DMW34_NATIVE_BUILD=$mwCTNativeDirectory","-DMW34_BINDINGS=$mwCTOut","-DMW34_REMILL_INCLUDE=$mwCTRoot/local/tools/remill-v6.0.1/remill-6.0.1/include","-DMW34_IMAGE=$mwCTRoot/MW3/Mech3.exe","-DMW34_PROVIDER=$mwCTRoot/local/mw3-staged/Shared_DLLs/MSVCRT.DLL","-DMW34_ORIGINAL_RAW=$mwCTOriginal") (Join-Path $mwCTOut 'configure.log')
 Invoke-MWCT $mwCTCMake @('--build',$mwCTBuild,'--parallel','8','--verbose') (Join-Path $mwCTOut 'build.log')
 Invoke-MWCT $mwCTCTest @('--test-dir',$mwCTBuild,'--verbose','--output-on-failure','--no-tests=error','--output-junit',(Join-Path $mwCTOut 'ctest.xml')) (Join-Path $mwCTOut 'ctest.log')
 foreach($mwCTPath in $mwCTSources.Keys){if((Get-MWCTHash $mwCTPath) -ne $mwCTSources[$mwCTPath]){throw 'Context source changed during build'}};$mwCTPassed=$true
}catch{$mwCTFailure=$_.Exception.Message;$_|Out-String|Set-Content -LiteralPath (Join-Path $mwCTOut 'failure.txt');throw}finally{
 $mwCTArtifacts=[ordered]@{};foreach($mwCTFile in @(Get-ChildItem -LiteralPath $mwCTOut -Recurse -File;if(Test-Path -LiteralPath $mwCTBuild){Get-ChildItem -LiteralPath $mwCTBuild -Recurse -File|Where-Object {$_.Extension -in @('.exe','.obj','.lib','.txt','.cmake','.json','.xml') -or $_.Name -in @('build.ninja','rules.ninja','.ninja_log')}})|Where-Object {$_.FullName -notmatch 'compiler-temp'}|Sort-Object FullName){$mwCTArtifacts[$mwCTFile.FullName]=Get-MWCTHash $mwCTFile.FullName}
 $mwCTTools=[ordered]@{};foreach($mwCTTool in @($mwCTCMake,$mwCTCTest,$mwCTNinja,(Get-Process -Id $PID).Path,(Join-Path $mwCTVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll'),(Get-Command rc.exe -ErrorAction SilentlyContinue).Source)+@('clang-cl.exe','llvm-lib.exe','lld-link.exe','llvm-mt.exe'|ForEach-Object {Join-Path $mwCTLLVM "bin/$_"})){if($mwCTTool -and (Test-Path -LiteralPath $mwCTTool)){$mwCTTools[$mwCTTool]=Get-MWCTHash $mwCTTool}}
 [ordered]@{passed=$mwCTPassed;failure=$mwCTFailure;scope='Actual compiled control-result plus selected26 carry and exact resident capability rejection controls; no full CRT startup credit';source_files=$mwCTSources;literal_source_copies=@($mwCTCopies);tool_files=$mwCTTools;artifacts=$mwCTArtifacts;commands=@($mwCTCommands);consumed_native_build_path=$mwCTNative;consumed_native_build_sha256=(Get-MWCTHash $mwCTNative);consumed_guest_objects=$mwCTMap.objects;whole_M4_complete=$false}|ConvertTo-Json -Depth 16|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mwCTOut 'build.json')
}
